CREATE OR REPLACE FUNCTION public.mt_editar_proposta_frequencia(_id uuid,_dados jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE antes jsonb; escala text[]:=ARRAY['semanal','quinzenal','mensal','trimestral','semestral']; f integer; m integer; r integer; p integer; BEGIN IF NOT coalesce(public.proj_gov_ou_ceo(auth.uid()),false) OR NOT (public.acesso_modulo(auth.uid(),'rotina',false) OR public.acesso_modulo(auth.uid(),'metas',false)) THEN RAISE EXCEPTION 'Sem permissão'; END IF; f:=array_position(escala,_dados->>'frequencia');m:=array_position(escala,_dados->>'velocidade_mudanca');r:=array_position(escala,_dados->>'velocidade_reacao');p:=array_position(escala,_dados->>'piso_fonte'); IF f IS NULL OR m IS NULL OR r IS NULL OR p IS NULL OR f<>greatest(m,r,p) THEN RAISE EXCEPTION 'Frequência deve ser a mais lenta entre mudança, reação e piso'; END IF; IF _dados->>'tratamento' NOT IN ('Pilotar','Suavizar','Vigiar por exceção','Revisar') OR nullif(btrim(_dados->>'frequencia_justificativa'),'') IS NULL THEN RAISE EXCEPTION 'Tratamento e justificativa obrigatórios'; END IF; IF f>=3 AND coalesce((_dados->>'semana_mes')::integer,0) NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Semana inválida'; END IF; IF f=4 AND coalesce((_dados->>'mes_ciclo')::integer,0) NOT BETWEEN 1 AND 3 OR f=5 AND coalesce((_dados->>'mes_ciclo')::integer,0) NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Mês inválido'; END IF; SELECT dados INTO antes FROM mt_frequencia_propostas WHERE indicador_id=_id AND status='proposto' FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM mt_indicadores WHERE id=_id AND origem IN ('okr','cesta')) THEN RAISE EXCEPTION 'Proposta não encontrada'; END IF; IF (_dados->>'fonte' ~* 'dre' OR EXISTS(SELECT 1 FROM mt_indicadores WHERE id=_id AND nome ~* 'ebitda|lucro|margem bruta|receita l.quida|despesas.*rol')) AND f<3 THEN RAISE EXCEPTION 'DRE exige piso mensal'; END IF; UPDATE mt_frequencia_propostas SET dados=_dados WHERE indicador_id=_id; INSERT INTO mt_auditoria(tabela,registro_id,campo,valor_anterior,valor_novo,alterado_por) VALUES('mt_frequencia_propostas',_id::text,'dados',antes::text,_dados::text,auth.uid()); END $$; REVOKE ALL ON FUNCTION public.mt_editar_proposta_frequencia(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mt_editar_proposta_frequencia(uuid,jsonb) TO authenticated;